// Invoice lifecycle status.
type InvoiceStatus string

const (
	// Invoice being prepared, not yet sent.
	InvoiceStatusDraft InvoiceStatus = "DRAFT"
	// Invoice sent, awaiting payment.
	InvoiceStatusPending InvoiceStatus = "PENDING"
	// Invoice paid in full.
	InvoiceStatusPaid InvoiceStatus = "PAID"
	// Payment past due date.
	InvoiceStatusOverdue InvoiceStatus = "OVERDUE"
	// Payment processing failed.
	InvoiceStatusFailed InvoiceStatus = "FAILED"
	// Invoice requires operator review and cannot be paid.
	InvoiceStatusManualReview InvoiceStatus = "MANUAL_REVIEW"
	// Invoice cancelled.
	InvoiceStatusCancelled InvoiceStatus = "CANCELLED"
)

var AllInvoiceStatus = []InvoiceStatus{
	InvoiceStatusDraft,
	InvoiceStatusPending,
	InvoiceStatusPaid,
	InvoiceStatusOverdue,
	InvoiceStatusFailed,
	InvoiceStatusManualReview,
	InvoiceStatusCancelled,
}

