// Operational mode controlling whether a node accepts new sessions. The mode
// is set via setNodeMode and snapshotted onto the node's heartbeat; routing
// inspects it via GetNodeHealth and steers around drained / maintenance nodes.
type NodeOperationalMode string

const (
	// Accepts new viewers and ingest. Default.
	NodeOperationalModeNormal NodeOperationalMode = "NORMAL"
	// Existing viewers continue; new viewers are routed elsewhere. Use before maintenance to bleed load gracefully.
	NodeOperationalModeDraining NodeOperationalMode = "DRAINING"
	// Hard out — node is removed from routing entirely. Existing sessions terminate.
	NodeOperationalModeMaintenance NodeOperationalMode = "MAINTENANCE"
)

var AllNodeOperationalMode = []NodeOperationalMode{
	NodeOperationalModeNormal,
	NodeOperationalModeDraining,
	NodeOperationalModeMaintenance,
}

